import{_ as a,o as t,c as i,a2 as o}from"./chunks/framework.CBxkvBm_.js";const u=JSON.parse('{"title":"Numerical ODE, DAE & Co-Simulation Solvers","description":"","frontmatter":{},"headers":[],"relativePath":"algorithms/solvers-ode-dae.md","filePath":"algorithms/solvers-ode-dae.md"}'),r={name:"algorithms/solvers-ode-dae.md"};function n(s,e,l,c,d,m){return t(),i("div",null,[...e[0]||(e[0]=[o('<h1 id="numerical-ode-dae-co-simulation-solvers" tabindex="-1">Numerical ODE, DAE &amp; Co-Simulation Solvers <a class="header-anchor" href="#numerical-ode-dae-co-simulation-solvers" aria-label="Permalink to &quot;Numerical ODE, DAE &amp; Co-Simulation Solvers&quot;">​</a></h1><p><strong>Implementation</strong>: <a href="https://github.com/modelscript/modelscript/tree/main/packages/simulate/src/solvers/" target="_blank" rel="noreferrer"><code>packages/simulate/src/solvers/</code></a> and <a href="https://github.com/modelscript/modelscript/tree/main/packages/runtime/src/solvers/" target="_blank" rel="noreferrer"><code>packages/runtime/src/solvers/</code></a></p><hr><h2 id="_1-tsitouras-5-4-adaptive-runge-kutta-tsit5" tabindex="-1">1. Tsitouras 5(4) Adaptive Runge-Kutta (Tsit5) <a class="header-anchor" href="#_1-tsitouras-5-4-adaptive-runge-kutta-tsit5" aria-label="Permalink to &quot;1. Tsitouras 5(4) Adaptive Runge-Kutta (Tsit5)&quot;">​</a></h2><h3 id="academic-citations" tabindex="-1">Academic Citations <a class="header-anchor" href="#academic-citations" aria-label="Permalink to &quot;Academic Citations&quot;">​</a></h3><ul><li><strong>Tsitouras, Ch. (2011)</strong>. <em>&quot;Runge-Kutta pairs of order 5 (4) satisfying only the first column simplifying assumption.&quot;</em><br><strong>Computers &amp; Mathematics with Applications</strong>, 62(2), pp. 770–775.<br> DOI: <a href="https://doi.org/10.1016/j.camwa.2011.06.002" target="_blank" rel="noreferrer">10.1016/j.camwa.2011.06.002</a></li><li><strong>Rackauckas, C., &amp; Nie, Q. (2017)</strong>. <em>&quot;DifferentialEquations.jl – A Performant and Feature-Rich Ecosystem for Solving Differential Equations in Julia.&quot;</em><br><strong>Journal of Open Research Software</strong>, 5(1), 15. DOI: <a href="https://doi.org/10.5334/jors.151" target="_blank" rel="noreferrer">10.5334/jors.151</a></li></ul><h3 id="modelscript-rationale-modifications" tabindex="-1">ModelScript Rationale &amp; Modifications <a class="header-anchor" href="#modelscript-rationale-modifications" aria-label="Permalink to &quot;ModelScript Rationale &amp; Modifications&quot;">​</a></h3><p>For non-stiff systems (e.g. mechanical multi-body dynamics, kinematics, flight control), high-order adaptive explicit Runge-Kutta pairs offer peak throughput without Newton-Raphson linear algebra costs. Tsit5 demonstrates significantly lower error coefficients and wider stability regions than classical Dormand-Prince (DOPRI5).</p><ul><li><strong>Modifications</strong>: Employs the First-Same-As-Last (FSAL) optimization eliminating stage 1 evaluation in successive steps; embeds a 5th-order continuous dense output polynomial for sub-interval event zero-crossing localization.</li></ul><hr><h2 id="_2-tr-bdf2-composite-stiff-solver" tabindex="-1">2. TR-BDF2 Composite Stiff Solver <a class="header-anchor" href="#_2-tr-bdf2-composite-stiff-solver" aria-label="Permalink to &quot;2. TR-BDF2 Composite Stiff Solver&quot;">​</a></h2><h3 id="academic-citations-1" tabindex="-1">Academic Citations <a class="header-anchor" href="#academic-citations-1" aria-label="Permalink to &quot;Academic Citations&quot;">​</a></h3><ul><li><strong>Bank, R. E., Coughran, W. M., et al. (1985)</strong>. <em>&quot;Transient simulation of silicon devices and circuits.&quot;</em><br><strong>IEEE Transactions on CAD of Integrated Circuits</strong>, 4(4), pp. 436–446.<br> DOI: <a href="https://doi.org/10.1109/TCAD.1985.1270142" target="_blank" rel="noreferrer">10.1109/TCAD.1985.1270142</a></li><li><strong>Hosea, M. E., &amp; Shampine, L. F. (1996)</strong>. <em>&quot;Analysis and implementation of TR-BDF2.&quot;</em><br><strong>Applied Numerical Mathematics</strong>, 20(1-2), pp. 21–37.<br> DOI: <a href="https://doi.org/10.1016/0168-9274(95)00115-8" target="_blank" rel="noreferrer">10.1016/0168-9274(95)00115-8</a></li></ul><h3 id="modelscript-rationale-modifications-1" tabindex="-1">ModelScript Rationale &amp; Modifications <a class="header-anchor" href="#modelscript-rationale-modifications-1" aria-label="Permalink to &quot;ModelScript Rationale &amp; Modifications&quot;">​</a></h3><p>Cyber-physical models featuring frequent hybrid discrete events (switches, impacts, hysteresis) severely penalize multistep BDF solvers (which must drop to order 1 after every event). TR-BDF2 is an L-stable one-step composite method pairing a trapezoidal half-step with a BDF2 completion step:</p><ul><li><strong>Modifications</strong>: Shares the diagonal Jacobian coefficient $d = 1 - 1/\\sqrt{2}$ across both internal stages, requiring only <strong>one</strong> sparse LU factorization per time step; connects directly with ModelScript&#39;s in-WASM sparse matrix kernel (<code>sparse_lu.ts</code>).</li></ul><hr><h2 id="_3-rodas-4p-linearly-implicit-rosenbrock-solver" tabindex="-1">3. RODAS-4P Linearly Implicit Rosenbrock Solver <a class="header-anchor" href="#_3-rodas-4p-linearly-implicit-rosenbrock-solver" aria-label="Permalink to &quot;3. RODAS-4P Linearly Implicit Rosenbrock Solver&quot;">​</a></h2><h3 id="academic-citations-2" tabindex="-1">Academic Citations <a class="header-anchor" href="#academic-citations-2" aria-label="Permalink to &quot;Academic Citations&quot;">​</a></h3><ul><li><strong>Steinebach, G. (1995)</strong>. <em>&quot;Order-reduction of ROW-methods for DAEs and method of lines applications.&quot;</em><br><strong>TH Darmstadt Preprint 1742</strong>.</li><li><strong>Hairer, E., &amp; Wanner, G. (1996)</strong>. <em>Solving Ordinary Differential Equations II: Stiff and Differential-Algebraic Problems</em>.<br><strong>Springer-Verlag</strong>. Section IV.8.</li></ul><h3 id="modelscript-rationale-modifications-2" tabindex="-1">ModelScript Rationale &amp; Modifications <a class="header-anchor" href="#modelscript-rationale-modifications-2" aria-label="Permalink to &quot;ModelScript Rationale &amp; Modifications&quot;">​</a></h3><p>Solves stiff index-1 DAEs and method-of-lines continuum discretizations without iterative non-linear Newton solves. It solves only a sequence of linear systems sharing the same system matrix $I - \\gamma h J$.</p><ul><li><strong>Modifications</strong>: Optimized for in-WASM sparse Jacobian caching; utilizes automatic differentiation coloring (<code>coloring.ts</code>) for fast Jacobian updates.</li></ul><hr><h2 id="_4-ito-stochastic-differential-equations-sde-solver" tabindex="-1">4. Itô Stochastic Differential Equations (SDE) Solver <a class="header-anchor" href="#_4-ito-stochastic-differential-equations-sde-solver" aria-label="Permalink to &quot;4. Itô Stochastic Differential Equations (SDE) Solver&quot;">​</a></h2><h3 id="academic-citations-3" tabindex="-1">Academic Citations <a class="header-anchor" href="#academic-citations-3" aria-label="Permalink to &quot;Academic Citations&quot;">​</a></h3><ul><li><strong>Rößler, A. (2010)</strong>. <em>&quot;Runge-Kutta methods for Itô stochastic differential equations with additive noise.&quot;</em><br><strong>SIAM Journal on Numerical Analysis</strong>, 48(3), pp. 922–952. DOI: <a href="https://doi.org/10.1137/09076636X" target="_blank" rel="noreferrer">10.1137/09076636X</a></li><li><strong>Kloeden, P. E., &amp; Platen, E. (1992)</strong>. <em>Numerical Solution of Stochastic Differential Equations</em>.<br><strong>Springer</strong>. DOI: <a href="https://doi.org/10.1007/978-3-662-12616-5" target="_blank" rel="noreferrer">10.1007/978-3-662-12616-5</a></li></ul><h3 id="modelscript-rationale-modifications-3" tabindex="-1">ModelScript Rationale &amp; Modifications <a class="header-anchor" href="#modelscript-rationale-modifications-3" aria-label="Permalink to &quot;ModelScript Rationale &amp; Modifications&quot;">​</a></h3><p>Physical systems operate under thermal noise, turbulence, and sensor fluctuations: $$dx = f(t, x) , dt + g(t, x) , dW_t$$</p><ul><li><strong>Modifications</strong>: Employs an in-WASM <code>Xoshiro256pp</code> PRNG with Box-Muller transformation; provides both fixed-step Euler-Maruyama (strong order 0.5) and adaptive Rößler SRIW1 (strong order 1.5) integrators for Monte Carlo uncertainty rollouts.</li></ul><hr><h2 id="_5-co-simulation-master-orchestrator" tabindex="-1">5. Co-Simulation Master Orchestrator <a class="header-anchor" href="#_5-co-simulation-master-orchestrator" aria-label="Permalink to &quot;5. Co-Simulation Master Orchestrator&quot;">​</a></h2><h3 id="academic-citations-4" tabindex="-1">Academic Citations <a class="header-anchor" href="#academic-citations-4" aria-label="Permalink to &quot;Academic Citations&quot;">​</a></h3><ul><li><strong>Bastian, J., et al. (2011)</strong>. <em>&quot;Master for Co-Simulation Using FMI.&quot;</em><br><strong>Proceedings of the 8th International Modelica Conference</strong>, pp. 115–120. DOI: <a href="https://doi.org/10.3384/ecp11063115" target="_blank" rel="noreferrer">10.3384/ecp11063115</a></li><li><strong>Kübler, R., &amp; Schiehlen, W. (2000)</strong>. <em>&quot;Two methods of simulator coupling.&quot;</em><br><strong>Mathematical and Computer Modelling of Dynamical Systems</strong>, 6(2), pp. 93–113. DOI: <a href="https://doi.org/10.1076/1387-3954(200006)6:2;1-M;FT093" target="_blank" rel="noreferrer">10.1076/1387-3954(200006)6:2;1-M;FT093</a></li></ul><h3 id="modelscript-rationale-modifications-4" tabindex="-1">ModelScript Rationale &amp; Modifications <a class="header-anchor" href="#modelscript-rationale-modifications-4" aria-label="Permalink to &quot;ModelScript Rationale &amp; Modifications&quot;">​</a></h3><p>Coordinates multi-rate, multi-vendor FMI Functional Mock-up Units (FMUs) and SSP topologies. Implements Richardson extrapolation error estimation to dynamically adapt the inter-simulator communication step size $H_{\\text{comm}}$, preventing divergence while maximizing simulation speed.</p><hr><h2 id="_6-dommel-companion-circuit-emt-bergeron-traveling-wave-solver" tabindex="-1">6. Dommel Companion-Circuit EMT &amp; Bergeron Traveling-Wave Solver <a class="header-anchor" href="#_6-dommel-companion-circuit-emt-bergeron-traveling-wave-solver" aria-label="Permalink to &quot;6. Dommel Companion-Circuit EMT &amp; Bergeron Traveling-Wave Solver&quot;">​</a></h2><h3 id="academic-citations-5" tabindex="-1">Academic Citations <a class="header-anchor" href="#academic-citations-5" aria-label="Permalink to &quot;Academic Citations&quot;">​</a></h3><ul><li><strong>Dommel, H. W. (1969)</strong>. <em>&quot;Digital Computer Solution of Electromagnetic Transients in Single- and Multiphase Networks.&quot;</em><br><strong>IEEE Transactions on Power Apparatus and Systems</strong>, PAS-88(4), pp. 388–399.<br> DOI: <a href="https://doi.org/10.1109/TPAS.1969.292459" target="_blank" rel="noreferrer">10.1109/TPAS.1969.292459</a></li><li><strong>Marti, J. R. (1982)</strong>. <em>&quot;Accurate Modelling of Frequency-Dependent Transmission Lines in Electromagnetic Transient Simulations.&quot;</em><br><strong>IEEE Transactions on Power Apparatus and Systems</strong>, PAS-101(1), pp. 147–157.<br> DOI: <a href="https://doi.org/10.1109/TPAS.1982.317332" target="_blank" rel="noreferrer">10.1109/TPAS.1982.317332</a></li></ul><h3 id="modelscript-rationale-modifications-5" tabindex="-1">ModelScript Rationale &amp; Modifications <a class="header-anchor" href="#modelscript-rationale-modifications-5" aria-label="Permalink to &quot;ModelScript Rationale &amp; Modifications&quot;">​</a></h3><p>Implemented in <code>EmtSolver</code> (<code>packages/simulate/src/solvers/emt/emt-solver.ts</code>), this solver targets microsecond-scale electromagnetic transients, power electronics switching (IGBTs/breakers), and distributed transmission lines imported from <code>@modelscript/pscad</code>:</p><ul><li><strong>Trapezoidal Companion Models &amp; Constant Nodal Matrix</strong>: Inductors ($G_L = \\frac{\\Delta t}{2L}$) and capacitors ($G_C = \\frac{2C}{\\Delta t}$) are discretized into Norton companion equivalents $\\mathbf{G}\\mathbf{v}(t) = \\mathbf{i}<em>{\\text{hist}}(t - \\Delta t) + \\mathbf{i}</em>{\\text{src}}(t)$, allowing $\\mathbf{G}$ to remain constant between switching events.</li><li><strong>Critical Damping Adjustment (CDA)</strong>: Automatically transitions from Trapezoidal to Backward Euler integration ($G_L = \\frac{\\Delta t}{L}, G_C = \\frac{C}{\\Delta t}$) for two half-steps ($\\Delta t / 2$) immediately after any breaker or semiconductor switching discontinuity to suppress artificial $dv/dt$ numerical oscillations.</li><li><strong>Bergeron Traveling-Wave Line Decoupling &amp; Norton FMU Interface</strong>: Distributed transmission lines with propagation delay $\\tau = \\ell / v \\ge \\Delta t$ decouple the nodal admittance matrix into independent sub-grids using interpolated history ring buffers, and expose <code>getNortonEquivalent(portNode)</code> ($I_{\\text{eq}}, G_{\\text{eq}}$) for zero-delay FMI Co-Simulation coupling.</li></ul><hr><h2 id="_7-high-order-taylor-model-flowpipe-integration" tabindex="-1">7. High-Order Taylor Model Flowpipe Integration <a class="header-anchor" href="#_7-high-order-taylor-model-flowpipe-integration" aria-label="Permalink to &quot;7. High-Order Taylor Model Flowpipe Integration&quot;">​</a></h2><h3 id="academic-citations-6" tabindex="-1">Academic Citations <a class="header-anchor" href="#academic-citations-6" aria-label="Permalink to &quot;Academic Citations&quot;">​</a></h3><ul><li><strong>Makino, K., &amp; Berz, M. (2003)</strong>. <em>&quot;Taylor Models and Other Validated Functional Inclusion Methods.&quot;</em><br><strong>International Journal of Pure and Applied Mathematics</strong>, 4(4), pp. 379–456.</li><li><strong>Chen, X., Ábrahám, E., &amp; Sankaranarayanan, S. (2013)</strong>. <em>&quot;Flow*: An Analyzer for Non-Linear Hybrid Systems.&quot;</em><br><strong>Computer Aided Verification (CAV 2013)</strong>, LNCS vol. 8044, pp. 258–263.<br> DOI: <a href="https://doi.org/10.1007/978-3-642-39799-8_18" target="_blank" rel="noreferrer">10.1007/978-3-642-39799-8_18</a></li></ul><h3 id="modelscript-rationale-modifications-6" tabindex="-1">ModelScript Rationale &amp; Modifications <a class="header-anchor" href="#modelscript-rationale-modifications-6" aria-label="Permalink to &quot;ModelScript Rationale &amp; Modifications&quot;">​</a></h3><p>Implemented in <code>TaylorModel</code> (<code>packages/runtime/src/analysis/wasm_taylor_model.ts</code>), validated Taylor Model arithmetic bounds all trajectories of a non-linear ODE/DAE system subject to uncertain initial sets $x(0) \\in X_0$ and parameter intervals without wrapping-effect blowup:</p><ul><li><strong>Polynomial + Interval Remainder Representation</strong>: Represents each state reachable tube over normalized domain $\\mathbf{z} \\in [-1, 1]^d$ as a multivariate polynomial $P_k(\\mathbf{z})$ of order $k$ plus a sound interval remainder $I = [\\underline{r}, \\overline{r}]$, where truncated higher-order terms ($&gt; k$) are conservatively swept into $I$.</li><li><strong>Picard-Lindelöf Validated Operator</strong>: Evaluates the contractive Picard integral operator $\\mathcal{P}(X)(t) = X_0 + \\int_0^t f(s, X(s)),ds$ directly on Taylor models to construct guaranteed continuous-time flowpipes consumed by <code>ContinuousSafetyOracle</code> and SysML v2 hybrid state-machine reachability (<code>hybrid-flowpipe-bridge.ts</code>).</li></ul><hr><h2 id="upstream-downstream-pipeline-connections" tabindex="-1">Upstream &amp; Downstream Pipeline Connections <a class="header-anchor" href="#upstream-downstream-pipeline-connections" aria-label="Permalink to &quot;Upstream &amp; Downstream Pipeline Connections&quot;">​</a></h2><ul><li><strong>Upstream Inputs</strong>: <ul><li>DAE blocks partitioned and torn by <a href="./blt.html"><code>BltEngine</code></a> and <a href="./tearing.html"><code>TornBlock</code></a>.</li><li>Sparse Jacobians computed via <a href="./surrogates-linear-algebra.html"><code>Dual Numbers &amp; Graph Coloring</code></a>.</li></ul></li><li><strong>Downstream Consumers</strong>: <ul><li>Powers <code>msx simulate</code>, <code>msx optimize</code>, and the Web IDE charting canvas.</li><li>Feeds state trajectories and validated flowpipes into <a href="./theory-coordinator.html"><code>Signal Temporal Logic (STL) Monitor &amp; Theory Coordinator</code></a> and formal verification oracles.</li></ul></li></ul>',53)])])}const h=a(r,[["render",n]]);export{u as __pageData,h as default};
